CREATE SCHEMA IF NOT EXISTS "public";

CREATE TYPE "AccountStatus" AS ENUM ('ACTIVE', 'INACTIVE');
CREATE TYPE "StudentStatus" AS ENUM ('ACTIVE', 'INACTIVE', 'GRADUATED', 'LEFT');
CREATE TYPE "RoomType" AS ENUM ('DOUBLE', 'FOUR_SEATER');
CREATE TYPE "RoomOperationalStatus" AS ENUM ('AVAILABLE', 'MAINTENANCE', 'UNAVAILABLE');
CREATE TYPE "AllocationStatus" AS ENUM ('ACTIVE', 'VACATED', 'CANCELLED');
CREATE TYPE "ApplicationStatus" AS ENUM ('SUBMITTED', 'APPROVED', 'REJECTED', 'WITHDRAWN');
CREATE TYPE "LeaveStatus" AS ENUM ('PENDING', 'APPROVED', 'REJECTED', 'DEPARTED', 'RETURNED', 'CANCELLED');
CREATE TYPE "LeaveEventType" AS ENUM ('SUBMITTED', 'APPROVED', 'REJECTED', 'DEPARTURE_VERIFIED', 'RETURN_VERIFIED', 'CANCELLED');
CREATE TYPE "ComplaintStatus" AS ENUM ('SUBMITTED', 'ASSIGNED', 'IN_PROGRESS', 'RESOLVED', 'CLOSED');
CREATE TYPE "ComplaintPriority" AS ENUM ('LOW', 'MEDIUM', 'HIGH', 'URGENT');
CREATE TYPE "EquipmentIssueStatus" AS ENUM ('ISSUED', 'RETURNED', 'LOST', 'CANCELLED');
CREATE TYPE "EquipmentCondition" AS ENUM ('GOOD', 'FAIR', 'DAMAGED', 'UNUSABLE');

CREATE TABLE "User" ("id" UUID NOT NULL, "email" VARCHAR(320) NOT NULL, "passwordHash" VARCHAR(255) NOT NULL, "fullName" VARCHAR(160) NOT NULL, "phone" VARCHAR(30), "status" "AccountStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Role" ("id" UUID NOT NULL, "code" VARCHAR(40) NOT NULL, "description" VARCHAR(255), CONSTRAINT "Role_pkey" PRIMARY KEY ("id"));
CREATE TABLE "UserRole" ("userId" UUID NOT NULL, "roleId" UUID NOT NULL, CONSTRAINT "UserRole_pkey" PRIMARY KEY ("userId", "roleId"));
CREATE TABLE "Student" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "enrollmentNumber" VARCHAR(32) NOT NULL, "admissionBatch" INTEGER NOT NULL, "branchCode" VARCHAR(12) NOT NULL, "academicYear" INTEGER, "status" "StudentStatus" NOT NULL DEFAULT 'ACTIVE', "guardianName" VARCHAR(160), "guardianPhone" VARCHAR(30), "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "Student_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Staff" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "designation" VARCHAR(120), "department" VARCHAR(120), CONSTRAINT "Staff_pkey" PRIMARY KEY ("id"));
CREATE TABLE "user_sessions" ("sid" VARCHAR(255) NOT NULL, "sess" JSONB NOT NULL, "expire" TIMESTAMP(6) NOT NULL, CONSTRAINT "user_sessions_pkey" PRIMARY KEY ("sid"));
CREATE TABLE "Floor" ("id" UUID NOT NULL, "number" INTEGER NOT NULL, "name" VARCHAR(100) NOT NULL, "description" TEXT, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "Floor_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Room" ("id" UUID NOT NULL, "floorId" UUID NOT NULL, "roomNumber" VARCHAR(20) NOT NULL, "roomType" "RoomType" NOT NULL, "capacity" INTEGER NOT NULL, "operationalStatus" "RoomOperationalStatus" NOT NULL DEFAULT 'AVAILABLE', "notes" TEXT, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "Room_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RoomAllocation" ("id" UUID NOT NULL, "studentId" UUID NOT NULL, "roomId" UUID NOT NULL, "allocatedBy" UUID NOT NULL, "status" "AllocationStatus" NOT NULL DEFAULT 'ACTIVE', "allocatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "vacatedAt" TIMESTAMPTZ(3), "reason" TEXT, CONSTRAINT "RoomAllocation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "HostelApplication" ("id" UUID NOT NULL, "studentId" UUID NOT NULL, "submittedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "status" "ApplicationStatus" NOT NULL DEFAULT 'SUBMITTED', "reviewedBy" UUID, "reviewedAt" TIMESTAMPTZ(3), "reviewNote" TEXT, CONSTRAINT "HostelApplication_pkey" PRIMARY KEY ("id"));
CREATE TABLE "LeaveRequest" ("id" UUID NOT NULL, "studentId" UUID NOT NULL, "departureAt" TIMESTAMPTZ(3) NOT NULL, "expectedReturnAt" TIMESTAMPTZ(3) NOT NULL, "destination" VARCHAR(255) NOT NULL, "reason" TEXT NOT NULL, "additionalInfo" TEXT, "status" "LeaveStatus" NOT NULL DEFAULT 'PENDING', "approverId" UUID, "approvedAt" TIMESTAMPTZ(3), "approverRemark" TEXT, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "LeaveRequest_pkey" PRIMARY KEY ("id"));
CREATE TABLE "LeaveEvent" ("id" UUID NOT NULL, "leaveId" UUID NOT NULL, "actorId" UUID NOT NULL, "type" "LeaveEventType" NOT NULL, "note" TEXT, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "LeaveEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ComplaintCategory" ("id" UUID NOT NULL, "name" VARCHAR(80) NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ComplaintCategory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Complaint" ("id" UUID NOT NULL, "studentId" UUID NOT NULL, "categoryId" UUID NOT NULL, "roomId" UUID, "description" TEXT NOT NULL, "priority" "ComplaintPriority" NOT NULL DEFAULT 'MEDIUM', "status" "ComplaintStatus" NOT NULL DEFAULT 'SUBMITTED', "assigneeId" UUID, "resolution" TEXT, "resolvedAt" TIMESTAMPTZ(3), "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "Complaint_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ComplaintHistory" ("id" UUID NOT NULL, "complaintId" UUID NOT NULL, "actorId" UUID NOT NULL, "fromStatus" "ComplaintStatus", "toStatus" "ComplaintStatus" NOT NULL, "remark" TEXT, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ComplaintHistory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Equipment" ("id" UUID NOT NULL, "name" VARCHAR(120) NOT NULL, "totalQuantity" INTEGER NOT NULL, "availableQuantity" INTEGER NOT NULL, "condition" "EquipmentCondition" NOT NULL DEFAULT 'GOOD', "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "Equipment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EquipmentIssue" ("id" UUID NOT NULL, "equipmentId" UUID NOT NULL, "studentId" UUID NOT NULL, "staffId" UUID NOT NULL, "quantity" INTEGER NOT NULL, "issuedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "expectedReturnAt" TIMESTAMPTZ(3), "returnedAt" TIMESTAMPTZ(3), "status" "EquipmentIssueStatus" NOT NULL DEFAULT 'ISSUED', "returnCondition" "EquipmentCondition", "notes" TEXT, CONSTRAINT "EquipmentIssue_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Notice" ("id" UUID NOT NULL, "title" VARCHAR(200) NOT NULL, "body" TEXT NOT NULL, "isPublished" BOOLEAN NOT NULL DEFAULT false, "publishedAt" TIMESTAMPTZ(3), "authorId" UUID NOT NULL, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "Notice_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PolicySetting" ("id" UUID NOT NULL, "key" VARCHAR(80) NOT NULL, "value" VARCHAR(255) NOT NULL, "description" TEXT, "updatedBy" UUID, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "PolicySetting_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditLog" ("id" UUID NOT NULL, "actorId" UUID, "action" VARCHAR(100) NOT NULL, "entityType" VARCHAR(80) NOT NULL, "entityId" VARCHAR(80) NOT NULL, "metadata" JSONB, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));

ALTER TABLE "Room" ADD CONSTRAINT "Room_capacity_positive" CHECK ("capacity" > 0);
ALTER TABLE "Equipment" ADD CONSTRAINT "Equipment_quantities_valid" CHECK ("totalQuantity" >= 0 AND "availableQuantity" >= 0 AND "availableQuantity" <= "totalQuantity");
ALTER TABLE "LeaveRequest" ADD CONSTRAINT "LeaveRequest_return_after_departure" CHECK ("expectedReturnAt" > "departureAt");

CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE UNIQUE INDEX "Role_code_key" ON "Role"("code");
CREATE INDEX "UserRole_roleId_idx" ON "UserRole"("roleId");
CREATE UNIQUE INDEX "Student_userId_key" ON "Student"("userId");
CREATE UNIQUE INDEX "Student_enrollmentNumber_key" ON "Student"("enrollmentNumber");
CREATE INDEX "Student_branchCode_admissionBatch_idx" ON "Student"("branchCode", "admissionBatch");
CREATE INDEX "Student_status_idx" ON "Student"("status");
CREATE UNIQUE INDEX "Staff_userId_key" ON "Staff"("userId");
CREATE INDEX "user_sessions_expire_idx" ON "user_sessions"("expire");
CREATE UNIQUE INDEX "Floor_number_key" ON "Floor"("number");
CREATE UNIQUE INDEX "Room_floorId_roomNumber_key" ON "Room"("floorId", "roomNumber");
CREATE INDEX "Room_floorId_operationalStatus_idx" ON "Room"("floorId", "operationalStatus");
CREATE INDEX "RoomAllocation_studentId_status_idx" ON "RoomAllocation"("studentId", "status");
CREATE INDEX "RoomAllocation_roomId_status_idx" ON "RoomAllocation"("roomId", "status");
CREATE INDEX "RoomAllocation_allocatedAt_idx" ON "RoomAllocation"("allocatedAt");
CREATE UNIQUE INDEX "RoomAllocation_one_active_student" ON "RoomAllocation"("studentId") WHERE "status" = 'ACTIVE';
CREATE UNIQUE INDEX "RoomAllocation_one_active_room_student_pair" ON "RoomAllocation"("roomId", "studentId") WHERE "status" = 'ACTIVE';
CREATE INDEX "HostelApplication_status_submittedAt_idx" ON "HostelApplication"("status", "submittedAt");
CREATE UNIQUE INDEX "HostelApplication_studentId_key" ON "HostelApplication"("studentId");
CREATE INDEX "LeaveRequest_studentId_createdAt_idx" ON "LeaveRequest"("studentId", "createdAt");
CREATE INDEX "LeaveRequest_status_departureAt_idx" ON "LeaveRequest"("status", "departureAt");
CREATE INDEX "LeaveEvent_leaveId_createdAt_idx" ON "LeaveEvent"("leaveId", "createdAt");
CREATE UNIQUE INDEX "ComplaintCategory_name_key" ON "ComplaintCategory"("name");
CREATE INDEX "Complaint_studentId_createdAt_idx" ON "Complaint"("studentId", "createdAt");
CREATE INDEX "Complaint_status_priority_idx" ON "Complaint"("status", "priority");
CREATE INDEX "Complaint_assigneeId_status_idx" ON "Complaint"("assigneeId", "status");
CREATE INDEX "ComplaintHistory_complaintId_createdAt_idx" ON "ComplaintHistory"("complaintId", "createdAt");
CREATE UNIQUE INDEX "Equipment_name_key" ON "Equipment"("name");
CREATE INDEX "EquipmentIssue_studentId_status_idx" ON "EquipmentIssue"("studentId", "status");
CREATE INDEX "EquipmentIssue_equipmentId_status_idx" ON "EquipmentIssue"("equipmentId", "status");
CREATE INDEX "Notice_isPublished_publishedAt_idx" ON "Notice"("isPublished", "publishedAt");
CREATE UNIQUE INDEX "PolicySetting_key_key" ON "PolicySetting"("key");
CREATE INDEX "AuditLog_entityType_entityId_idx" ON "AuditLog"("entityType", "entityId");
CREATE INDEX "AuditLog_actorId_createdAt_idx" ON "AuditLog"("actorId", "createdAt");

ALTER TABLE "UserRole" ADD CONSTRAINT "UserRole_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "UserRole" ADD CONSTRAINT "UserRole_roleId_fkey" FOREIGN KEY ("roleId") REFERENCES "Role"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Student" ADD CONSTRAINT "Student_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Staff" ADD CONSTRAINT "Staff_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Room" ADD CONSTRAINT "Room_floorId_fkey" FOREIGN KEY ("floorId") REFERENCES "Floor"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "RoomAllocation" ADD CONSTRAINT "RoomAllocation_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "RoomAllocation" ADD CONSTRAINT "RoomAllocation_roomId_fkey" FOREIGN KEY ("roomId") REFERENCES "Room"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "RoomAllocation" ADD CONSTRAINT "RoomAllocation_allocatedBy_fkey" FOREIGN KEY ("allocatedBy") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "HostelApplication" ADD CONSTRAINT "HostelApplication_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "HostelApplication" ADD CONSTRAINT "HostelApplication_reviewedBy_fkey" FOREIGN KEY ("reviewedBy") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "LeaveRequest" ADD CONSTRAINT "LeaveRequest_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "LeaveRequest" ADD CONSTRAINT "LeaveRequest_approverId_fkey" FOREIGN KEY ("approverId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "LeaveEvent" ADD CONSTRAINT "LeaveEvent_leaveId_fkey" FOREIGN KEY ("leaveId") REFERENCES "LeaveRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LeaveEvent" ADD CONSTRAINT "LeaveEvent_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Complaint" ADD CONSTRAINT "Complaint_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Complaint" ADD CONSTRAINT "Complaint_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "ComplaintCategory"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Complaint" ADD CONSTRAINT "Complaint_roomId_fkey" FOREIGN KEY ("roomId") REFERENCES "Room"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Complaint" ADD CONSTRAINT "Complaint_assigneeId_fkey" FOREIGN KEY ("assigneeId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ComplaintHistory" ADD CONSTRAINT "ComplaintHistory_complaintId_fkey" FOREIGN KEY ("complaintId") REFERENCES "Complaint"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ComplaintHistory" ADD CONSTRAINT "ComplaintHistory_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "EquipmentIssue" ADD CONSTRAINT "EquipmentIssue_equipmentId_fkey" FOREIGN KEY ("equipmentId") REFERENCES "Equipment"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "EquipmentIssue" ADD CONSTRAINT "EquipmentIssue_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "EquipmentIssue" ADD CONSTRAINT "EquipmentIssue_staffId_fkey" FOREIGN KEY ("staffId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Notice" ADD CONSTRAINT "Notice_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "PolicySetting" ADD CONSTRAINT "PolicySetting_updatedBy_fkey" FOREIGN KEY ("updatedBy") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
